/**
 *
 * AutoCompleteIndicator is the dropdown indicator element for the AutoComplete component.
 *
 * [Live Demo](https://www.primereact.org/autocomplete/)
 *
 * @module AutoCompleteIndicator
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { AutoCompleteRootInstance } from './AutoCompleteRoot.types';
/**
 * Defines passthrough(pt) options type in AutoCompleteIndicator component.
 */
export type AutoCompleteIndicatorPassThroughType<E> = PassThroughType<AutoCompleteIndicatorInstance, E>;
/**
 * Defines passthrough(pt) options of AutoCompleteIndicator component.
 */
export interface AutoCompleteIndicatorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: AutoCompleteIndicatorPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in AutoCompleteIndicator component.
 */
export interface AutoCompleteIndicatorProps extends BaseComponentProps<AutoCompleteIndicatorInstance, unknown, AutoCompleteIndicatorPassThrough> {
    /**
     * Determines the visibility of the indicator based on the state of the autocomplete.
     * - "open": Indicator is visible when the dropdown is open.
     * - "closed": Indicator is visible when the dropdown is closed.
     * - "always": Indicator is always visible.
     * @defaultValue 'always'
     */
    match?: 'open' | 'closed' | 'always' | undefined;
}
/**
 * Defines valid state in AutoCompleteIndicator component.
 */
export interface AutoCompleteIndicatorState {
}
/**
 * Defines the methods and properties exposed by AutoCompleteIndicator component.
 */
export interface AutoCompleteIndicatorExposes {
    /**
     * The AutoComplete component instance.
     */
    autocomplete: AutoCompleteRootInstance | undefined | null;
}
/**
 * Instance of AutoCompleteIndicator component.
 */
export type AutoCompleteIndicatorInstance = ComponentInstance<AutoCompleteIndicatorProps, AutoCompleteIndicatorState, AutoCompleteIndicatorExposes>;
